<?php defined('BASEPATH') or exit('No direct script access allowed'); $position=$payable['position']; $document=$position['document']; $requestForPayable=$workspace['request']['id']??null; ?>
<article class="purchase-section" data-payable-id="<?= (int)$payable['id'] ?>"><h3><?= $e($document['reference'].' / '.$document['vendor_number']) ?></h3><p><?= $e($position['supplier_name']) ?> · <?= $e($position['order_reference']) ?> · Vencimento <?= $e($payable['due_date']) ?></p><p><strong><?= $e($payable['currency']) ?> <?= $money($payable['amount_cents']) ?></strong> · Quitação declarada <?= $money($position['declared_paid_cents']) ?> · Em aberto <strong><?= $money($position['outstanding_cents']) ?></strong></p><p><a href="<?= $e(CompanyRequestScope::adminUrl($this,'expenses?expense='.(int)$payable['expense_id'])) ?>">Despesa canônica #<?= (int)$payable['expense_id'] ?></a></p>
<?php if ($capabilities['pay']&&$position['outstanding_cents']>0) { ?><details><summary>Declarar quitação externa</summary><p>Registre somente um pagamento já realizado fora deste fluxo. A confirmação abaixo é sua declaração; nenhum banco será acionado.</p><?php $form('settle',$payable['id'],$position['revision_token'],$requestForPayable); ?><div class="purchase-grid"><label>Valor (<?= $e($payable['currency']) ?>)<input class="form-control" name="purchase[amount]" inputmode="decimal" value="<?= $money($position['outstanding_cents']) ?>" required></label><label>Data da quitação<input class="form-control" type="date" name="purchase[event_date]" min="<?= $e($document['document_date']) ?>" max="<?= gmdate('Y-m-d') ?>" value="<?= gmdate('Y-m-d') ?>" required></label><label>Referência externa<input class="form-control" name="purchase[external_reference]" maxlength="191" required></label></div><label>Observações<textarea class="form-control" name="purchase[note]" maxlength="2000"></textarea></label><?php if ($requestForPayable!==null) { ?><label>Comprovante já anexado<select class="form-control" name="purchase[file_id]"><option value="">Sem arquivo adicional</option><?php foreach ($files as $file) { ?><option value="<?= (int)$file['id'] ?>"><?= $e($file['filename']) ?></option><?php } ?></select></label><?php } ?><label><input type="checkbox" name="purchase[acknowledged]" value="1" required> Confirmo que estou declarando uma quitação externa já realizada, sem ordem bancária automática.</label><button>Registrar declaração de quitação</button></form></details><?php } ?>
<?php if ($position['events']) { ?><details><summary>Histórico de declarações e reversões</summary><div class="table-responsive"><table class="purchase-table"><thead><tr><th>Evento</th><th>Data</th><th>Valor</th><th>Referência / motivo</th><th>Ação</th></tr></thead><tbody><?php $reversed=[]; foreach ($position['events'] as $event) { if ($event['reverses_id']!==null) { $reversed[(int)$event['reverses_id']]=true; } } foreach ($position['events'] as $event) { ?><tr><td><?= $event['kind']==='manual_external_settlement'?'Quitação declarada':'Reversão da declaração #'.(int)$event['reverses_id'] ?></td><td><?= $e($event['event_date']) ?></td><td><?= $money($event['amount_cents']) ?></td><td><?= $e($event['external_reference']) ?><br><?= $e($event['note']) ?></td><td><?php if ($capabilities['pay']&&$event['kind']==='manual_external_settlement'&&!isset($reversed[(int)$event['id']])) { $form('reverse',$event['id'],$position['revision_token'],$requestForPayable); ?><label>Data<input type="date" name="purchase[event_date]" value="<?= gmdate('Y-m-d') ?>" max="<?= gmdate('Y-m-d') ?>" required></label><label>Motivo<textarea name="purchase[reason]" maxlength="2000" required></textarea></label><label><input type="checkbox" name="purchase[acknowledged]" value="1" required> Corrigir somente a declaração; nenhuma devolução bancária será executada.</label><button>Reverter declaração inteira</button></form><?php } ?></td></tr><?php } ?></tbody></table></div></details><?php } ?></article>
